{"implementation":"import math

def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case fields")
    nodes = case["nodes"]
    required = case["required_symbols"]
    if not isinstance(nodes, list) or not isinstance(required, list):
        raise ValueError("invalid case field types")
    if any(not isinstance(symbol, str) for symbol in required):
        raise ValueError("required symbols must be strings")

    by_id = {}
    root_id = None
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("node must be an object")
        fields = ("id", "parent", "symbol", "depth", "removable", "utility")
        if any(field not in node for field in fields):
            raise ValueError("missing node field")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]
        if not isinstance(node_id, str) or node_id in by_id:
            raise ValueError("invalid or duplicate node ID")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("invalid parent")
        if not isinstance(symbol, str):
            raise ValueError("invalid symbol")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("invalid depth")
        if not isinstance(removable, bool):
            raise ValueError("invalid removable flag")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError("invalid utility")
        by_id[node_id] = node
        if parent is None:
            if root_id is not None:
                raise ValueError("multiple roots")
            root_id = node_id
    if root_id is None:
        raise ValueError("missing root")

    children = {node_id: [] for node_id in by_id}
    for node in nodes:
        parent = node["parent"]
        if parent is not None:
            if parent not in by_id or node["depth"] != by_id[parent]["depth"] + 1:
                raise ValueError("invalid tree structure")
            children[parent].append(node["id"])
    for node_id in by_id:
        current = node_id
        seen = set()
        while current is not None:
            if current in seen:
                raise ValueError("cycle in tree")
            seen.add(current)
            current = by_id[current]["parent"]
        if root_id not in seen:
            raise ValueError("disconnected tree")

    required_set = set(required)
    if any(node["symbol"] not in {n["symbol"] for n in nodes} for node in []):
        raise ValueError("invalid required symbols")
    retained = set(by_id)
    removed = []
    candidates = sorted(nodes, key=lambda node: (-node["depth"], node["id"]))
    for node in candidates:
        node_id = node["id"]
        if node_id == root_id or not node["removable"] or node["symbol"] in required_set:
            continue
        if any(child in retained for child in children[node_id]):
            continue
        trial = retained - {node_id}
        if any(symbol not in {by_id[item]["symbol"] for item in trial} for symbol in required_set):
            continue
        retained.remove(node_id)
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained)
    }
"}
